"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto

# Block lifecycle states for the confirm/rollback state machine.
STATUS_PENDING = "pending"
STATUS_CONFIRMED = "confirmed"
BLOCK_STATUSES = (STATUS_PENDING, STATUS_CONFIRMED)


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str

    @property
    def message(self) -> bytes:
        return crypto.canonical_message(self.sender, self.recipient, self.amount)

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        return {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
            "tx_id": self.tx_id,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        # The raw JSON value is validated BEFORE any use: no int()/str()
        # coercion, so a string, float or boolean amount can never masquerade
        # as the integer it converts to. bool is an int subclass and must be
        # rejected explicitly.
        amount = data["amount"]
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("transaction amount must be an integer")
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=amount,
            signature=data["signature"],
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str
    status: str = STATUS_CONFIRMED

    @classmethod
    def create(
        cls,
        height: int,
        prev_hash: str,
        transactions: list[Transaction],
        status: str = STATUS_CONFIRMED,
    ) -> "Block":
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
            status=status,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "status": self.status,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        # State files written before the status machine existed have no
        # "status" key; every block in such a file was final, so they load
        # as confirmed. This compatibility default never extends to numeric
        # coercion: the raw height must already be a non-boolean,
        # non-negative integer — a string, float or bool is rejected, never
        # converted.
        status = data.get("status", STATUS_CONFIRMED)
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        height = data["height"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            raise ValueError("block height must be a non-negative integer")
        transactions = data["transactions"]
        if not isinstance(transactions, list):
            raise ValueError("block transactions must be a list")
        return cls(
            height=height,
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in transactions],
            status=status,
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "status": self.status,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

"""Cryptographic helpers: Ed25519 verification, SHA-256 ids and Merkle roots."""
from __future__ import annotations

import hashlib
import hmac
import json
import re

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)


def canonical_message(sender: str, recipient: str, amount: int) -> bytes:
    """Deterministic byte representation of a transaction payload.

    The payload is serialized as compact JSON with sorted keys so the same
    (from, to, amount) triple always yields identical bytes on every client.
    """
    payload = {"amount": amount, "from": sender, "to": recipient}
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def compute_tx_id(message: bytes) -> str:
    """SHA-256 hex digest of the canonical transaction message."""
    return sha256_hex(message)


def generate_private_key() -> str:
    """Generate a fresh Ed25519 private seed as 64 lowercase hex chars."""
    return Ed25519PrivateKey.generate().private_bytes(
        serialization.Encoding.Raw,
        serialization.PrivateFormat.Raw,
        serialization.NoEncryption(),
    ).hex()


def derive_public_key(private_key_hex: str) -> str | None:
    """Derive the 64-hex Ed25519 public key from a 64-hex private seed.

    Returns None for malformed hex or a wrong-length seed rather than raising,
    so callers can treat every malformed key uniformly as a 400.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return _public_hex(private_key)


def _public_hex(private_key: Ed25519PrivateKey) -> str:
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def sign_message(private_key_hex: str, message: bytes) -> str | None:
    """Sign ``message`` with an Ed25519 seed (64 hex chars); hex signature.

    Returns None for a malformed private key rather than raising.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return private_key.sign(message).hex()


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


def verify_merkle_proof(
    tx_id: str,
    siblings: list[dict],
    merkle_root: str,
    block_hash: str,
    expected_block_hash: str,
) -> bool:
    """Verify a Merkle proof and bind it to a specific block hash.

    Re-hashes the leaf (``tx_id``) with the sibling path from leaf to root and
    compares the result with ``merkle_root``; ``block_hash`` must additionally
    equal ``expected_block_hash``. Every malformed input (non-64-char lowercase
    hex hash, illegal direction, non-list path, excessive depth) and every
    mismatch returns False rather than raising.
    """
    try:
        if not _is_hex64(tx_id):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_block_hash):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        current = tx_id
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            if direction == "left":
                pair = sibling_hash + current
            elif direction == "right":
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))

        if not hmac.compare_digest(current, merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False

"""Ledger business logic: submit transactions, mine blocks, query state,
and drive the confirm/rollback block state machine.

Block lifecycle
---------------
The genesis block is born ``confirmed``. Mining (POST /v1/blocks) is only
allowed when the chain tip is confirmed and the mempool is non-empty; it
produces a ``pending`` block. A pending tip can then be *confirmed* (making
its transactions count toward balances and proofs) or *rolled back* (the
block is deleted and its transactions return to the mempool de-duplicated).
Only the tip can ever be pending, so a confirmed block is final.

Balance convention
------------------
The contract defines no minting endpoint, so every identity starts with a
fixed endowment (``initial_balance``, overridable via LEDGER_INITIAL_BALANCE).
An account's confirmed balance is::

    initial_balance + sum(confirmed amounts received) - sum(confirmed amounts sent)

Only confirmed blocks count. The reported balance additionally subtracts the
account's spends sitting in the pending (unconfirmed) tip block — pending
*credits* are deliberately not counted. An identity only becomes a *queryable
account* once it appears in a confirmed block; GET account before that
returns 404. Balance checks at submission time treat an identity that has
never appeared on chain as holding the initial endowment, otherwise the first
transaction in an empty ledger could never be accepted.
"""
from __future__ import annotations

import hashlib
import json
import time

from . import audit
from . import crypto
from .models import STATUS_CONFIRMED, STATUS_PENDING, Block, Transaction
from .store import TRUST_ACTIVE, TRUST_REVOKED, LedgerStore

DEFAULT_INITIAL_BALANCE = 1_000_000

REQUIRED_TX_FIELDS = ("from", "to", "amount", "signature")

# Audit event kinds. The log is append-only: trust lifecycle changes
# (registered/rotated/revoked) and inter-node sync events
# (received/adopted/expired) are all recorded permanently.
EVENT_SOURCE_REGISTERED = "source_registered"
EVENT_SOURCE_ROTATED = "source_rotated"
EVENT_SOURCE_REVOKED = "source_revoked"
EVENT_SYNC_RECEIVED = "sync_received"
EVENT_SYNC_ADOPTED = "sync_adopted"
EVENT_SYNC_EXPIRED = "sync_expired"
EVENT_AUDIT_SIGNER_ROTATED = "audit_signer_rotated"
EVENT_ALLOWLIST_ADDED = "allowlist_added"
EVENT_ALLOWLIST_REMOVED = "allowlist_removed"


def _parse_height(height: object) -> int | None:
    """Strict decimal height parse; None when malformed."""
    try:
        height_int = int(height)  # type: ignore[arg-type]
        if str(height_int) != str(height).strip():
            raise ValueError
        return height_int
    except (TypeError, ValueError):
        return None


def _parse_decimal(value: object) -> int | None:
    """Strict non-negative decimal parse; None when malformed.

    Only ``0`` or a digit string whose first digit is non-zero is accepted:
    leading zeros, signs, whitespace and non-string types are all rejected.
    """
    if not isinstance(value, str) or not value:
        return None
    if value != "0" and (not value.isdigit() or value[0] == "0"):
        return None
    return int(value)


class LedgerService:
    def __init__(self, store: LedgerStore, initial_balance: int = DEFAULT_INITIAL_BALANCE) -> None:
        self.store = store
        # The snapshot-recorded endowment is the only balance-replay / balance
        # reporting parameter: a recovered store already knows its endowment, so
        # restarting with a different --initial-balance must not change any
        # legality or reported balance. Only a brand-new store (no recorded
        # value) adopts the constructor argument.
        if store.initial_balance is None:
            store.initial_balance = initial_balance
            self.initial_balance = initial_balance
        else:
            self.initial_balance = store.initial_balance

    # -- transactions -------------------------------------------------------

    def submit_transaction(self, payload: object) -> tuple[int, dict]:
        """Validate and enqueue a transaction. Returns (status, body)."""
        if not isinstance(payload, dict):
            return 400, {"error": "request body must be a JSON object"}
        for field in REQUIRED_TX_FIELDS:
            if field not in payload:
                return 400, {"error": f"missing field: {field}"}

        sender = payload["from"]
        recipient = payload["to"]
        amount = payload["amount"]
        signature = payload["signature"]

        if not isinstance(sender, str) or not sender:
            return 400, {"error": "field 'from' must be a non-empty string"}
        if not isinstance(recipient, str) or not recipient:
            return 400, {"error": "field 'to' must be a non-empty string"}
        # bool is a subclass of int: reject it and all non-int types explicitly.
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            return 400, {"error": "field 'amount' must be a positive integer"}
        if not isinstance(signature, str) or not signature:
            return 400, {"error": "field 'signature' must be a non-empty string"}

        message = crypto.canonical_message(sender, recipient, amount)
        if not crypto.verify_signature(sender, message, signature):
            return 400, {"error": "invalid signature"}

        tx = Transaction(sender, recipient, amount, signature)
        with self.store.lock:
            if tx.tx_id in self.store.pending:
                return 409, {"error": "transaction already pending", "tx_id": tx.tx_id}
            if any(tx.tx_id == existing.tx_id for block in self.store.chain for existing in block.transactions):
                return 409, {"error": "transaction already confirmed", "tx_id": tx.tx_id}
            if self.available_balance(sender) < amount:
                return 400, {"error": "insufficient balance"}
            self.store.pending[tx.tx_id] = tx
            try:
                self.store.save()
            except BaseException:
                # Persistence failed: drop the in-memory enqueue so memory
                # keeps matching the last durably committed state.
                self.store.pending.pop(tx.tx_id, None)
                raise
        return 202, {"tx_id": tx.tx_id}

    # -- blocks -------------------------------------------------------------

    def mine_block(self) -> tuple[int, dict]:
        """Pack all pending transactions (ascending tx_id) into a pending block.

        Only allowed when the chain tip is confirmed; the new block becomes
        the pending tip until it is confirmed or rolled back.
        """
        with self.store.lock:
            if self.store.tip_is_pending():
                return 409, {"error": "tip block is pending confirmation"}
            if not self.store.pending:
                return 409, {"error": "no pending transactions"}
            ordered = sorted(self.store.pending.values(), key=lambda tx: tx.tx_id)
            block = Block.create(
                height=self.store.next_height(),
                prev_hash=self.store.tip_hash(),
                transactions=ordered,
                status=STATUS_PENDING,
            )
            self.store.chain.append(block)
            removed = [self.store.pending.pop(tx.tx_id) for tx in ordered]
            try:
                self.store.save()
            except BaseException:
                # Undo the in-memory block so nothing un-persisted is visible.
                self.store.chain.pop()
                self.store.pending.update({tx.tx_id: tx for tx in removed})
                raise
        return 201, {
            "height": block.height,
            "block_hash": block.block_hash,
            "merkle_root": block.merkle_root,
            "status": block.status,
        }

    def get_block(self, height: object) -> tuple[int, dict]:
        height_int = _parse_height(height)
        if height_int is None:
            return 404, {"error": "block not found"}
        with self.store.lock:
            block = self.store.block_at(height_int)
            if block is None:
                return 404, {"error": "block not found"}
            return 200, block.to_summary()

    def get_block_status(self, height: object) -> tuple[int, dict]:
        """GET /v1/blocks/{height}/status -> {height, status}; 404 if unknown."""
        height_int = _parse_height(height)
        if height_int is None:
            return 404, {"error": "block not found"}
        with self.store.lock:
            block = self.store.block_at(height_int)
            if block is None:
                return 404, {"error": "block not found"}
            return 200, {"height": block.height, "status": block.status}

    def confirm_block(self, height: object) -> tuple[int, dict]:
        """Confirm a pending tip block.

        Only a pending chain tip whose parent is confirmed can be confirmed.
        Confirming an already-confirmed block is idempotent (200); every
        other case — unknown or malformed height, non-tip pending block —
        returns 409.
        """
        height_int = _parse_height(height)
        with self.store.lock:
            if height_int is None:
                return 409, {"error": "block cannot be confirmed"}
            block = self.store.block_at(height_int)
            if block is None:
                return 409, {"error": "block cannot be confirmed"}
            if block.status == STATUS_CONFIRMED:
                # Idempotent re-confirm.
                return 200, {"height": block.height, "status": STATUS_CONFIRMED}
            if block is not self.store.tip():
                return 409, {"error": "only the chain tip can be confirmed"}
            parent = self.store.chain[-2] if len(self.store.chain) >= 2 else None
            if parent is None or parent.status != STATUS_CONFIRMED:
                return 409, {"error": "previous block is not confirmed"}
            block.status = STATUS_CONFIRMED
            try:
                self.store.save()
            except BaseException:
                block.status = STATUS_PENDING
                raise
            return 200, {"height": block.height, "status": STATUS_CONFIRMED}

    def rollback_block(self, height: object) -> tuple[int, dict]:
        """Roll back a pending tip block: delete it and restore its transactions.

        Unknown or malformed heights (including an already-rolled-back
        height) return 404; a confirmed block or a non-tip block returns 409.
        """
        height_int = _parse_height(height)
        if height_int is None:
            return 404, {"error": "block not found"}
        with self.store.lock:
            block = self.store.block_at(height_int)
            if block is None:
                return 404, {"error": "block not found"}
            if block.status == STATUS_CONFIRMED:
                return 409, {"error": "confirmed block cannot be rolled back"}
            if block is not self.store.tip():
                return 409, {"error": "only the chain tip can be rolled back"}
            pending_before = set(self.store.pending)
            rolled_back = self.store.rollback_tip()
            try:
                self.store.save()
            except BaseException:
                # Restore the block and drop only the mempool entries we added.
                self.store.chain.append(rolled_back)
                for tx_id in list(self.store.pending):
                    if tx_id not in pending_before:
                        del self.store.pending[tx_id]
                raise
            return 200, {"height": rolled_back.height, "status": "rolled_back"}

    def get_proof(self, height: object, tx_id: object) -> tuple[int, dict]:
        """Return a Merkle inclusion proof for tx_id at the given height.

        Returns 404 for an unknown height, a malformed height/tx_id, or a
        transaction absent from that block. Proofs are only issued for
        confirmed blocks; a pending block returns 409.
        """
        height_int = _parse_height(height)
        if height_int is None:
            return 404, {"error": "block not found"}
        if not crypto.is_hex64(tx_id):
            return 404, {"error": "transaction not found"}
        with self.store.lock:
            block = self.store.block_at(height_int)
            if block is None:
                return 404, {"error": "block not found"}
            if block.status != STATUS_CONFIRMED:
                return 409, {"error": "block is pending confirmation"}
            tx_ids = [tx.tx_id for tx in block.transactions]
            try:
                index = tx_ids.index(tx_id)
            except ValueError:
                return 404, {"error": "transaction not found"}
            siblings = crypto.merkle_proof(tx_ids, index)
            return 200, {
                "height": block.height,
                "tx_id": tx_id,
                "index": index,
                "merkle_root": block.merkle_root,
                "block_hash": block.block_hash,
                "siblings": siblings,
            }

    # -- accounts -----------------------------------------------------------

    def get_account(self, account: str) -> tuple[int, dict]:
        with self.store.lock:
            entry = self.store.accounts.get(account)
            if entry is None:
                return 404, {"error": "account not found"}
            return 200, {
                "account": account,
                "balance": self.reported_balance(account),
                "confirmed_transactions": list(entry["transactions"]),
            }

    def confirmed_balance(self, account: str) -> int:
        """Balance from confirmed blocks only."""
        entry = self.store.accounts.get(account)
        if entry is None:
            return self.initial_balance
        return self.initial_balance + entry["received"] - entry["sent"]

    def reported_balance(self, account: str) -> int:
        """Confirmed balance minus spends sitting in the pending tip block.

        Pending-block credits are not counted: unconfirmed income can still
        be rolled back, so it must not inflate the reported balance.
        """
        balance = self.confirmed_balance(account)
        tip = self.store.tip()
        if tip.status == STATUS_PENDING:
            for tx in tip.transactions:
                if tx.sender == account:
                    balance -= tx.amount
        return balance

    def available_balance(self, account: str) -> int:
        """Reported balance minus amounts already committed in the mempool.

        Pending credits (mempool or unconfirmed block) are deliberately not
        counted, so a sequence of submissions cannot spend money that has not
        been confirmed yet.
        """
        balance = self.reported_balance(account)
        for tx in self.store.pending.values():
            if tx.sender == account:
                balance -= tx.amount
        return balance

    # -- fork candidates -----------------------------------------------------

    @staticmethod
    def _fork_summary(blocks: list) -> dict:
        """Public fork descriptor S: tip_hash, height, length, status."""
        tip = blocks[-1]
        return {
            "tip_hash": tip.block_hash,
            "height": tip.height,
            # The length counts every block including the genesis block.
            "length": len(blocks),
            "status": tip.status,
        }

    def _winning_fork(self) -> tuple[str, list]:
        """Pick the winner among the canonical chain and every candidate.

        Longest chain wins; equal lengths are broken by the smallest tip hash
        (lexicographic hex order). Returns (tip_hash, block list).
        """
        contenders: list[tuple[str, list]] = [
            (self.store.tip_hash(), self.store.chain)
        ]
        contenders.extend(self.store.forks.items())
        contenders.sort(key=lambda item: (-len(item[1]), item[0]))
        return contenders[0]

    def submit_fork_candidate(self, payload: object) -> tuple[int, dict]:
        """POST /v1/forks/candidates — validate and store a candidate fork.

        Returns 201 with the fork descriptor S. Malformed or invalid forks
        return 400; a fork already known (identical to the canonical tip or an
        existing candidate tip) returns 409.
        """
        if not isinstance(payload, dict):
            return 400, {"error": "request body must be a JSON object"}
        blocks_raw = payload.get("blocks")
        if not isinstance(blocks_raw, list):
            return 400, {"error": "missing field: blocks (must be a list)"}
        try:
            fork = self.store.validate_fork_blocks(blocks_raw)
        except ValueError as exc:
            return 400, {"error": str(exc)}
        summary = self._fork_summary(fork)
        # An exported fork (the five-field {tip_hash, height, length, status,
        # blocks} document) may be resubmitted verbatim; every supplied summary
        # field is re-verified against the recomputed descriptor.
        for field in ("tip_hash", "height", "length", "status"):
            if field in payload and payload[field] != summary[field]:
                return 400, {"error": f"summary field {field!r} does not match the blocks"}
        tip_hash = fork[-1].block_hash
        with self.store.lock:
            self._prune_expired_syncs()
            # A tip hash equal to any canonical block hash means the candidate
            # is exactly the canonical chain or a prefix of it (the block hash
            # binds height, parent and Merkle root), so it carries nothing new.
            if any(tip_hash == block.block_hash for block in self.store.chain):
                return 409, {"error": "fork is identical to the canonical chain"}
            if tip_hash in self.store.forks:
                return 409, {"error": "candidate fork already exists", "tip_hash": tip_hash}
            self.store.forks[tip_hash] = fork
            try:
                self.store.save()
            except BaseException:
                self.store.forks.pop(tip_hash, None)
                raise
        return 201, self._fork_summary(fork)

    def get_chain(self) -> tuple[int, dict]:
        """GET /v1/chain — canonical chain, candidates sorted by tip hash and
        the adoptable winner (a non-canonical chain that beats canonical).
        """
        with self.store.lock:
            self._prune_expired_syncs()
            canonical = self._fork_summary(self.store.chain)
            candidates = [
                self._fork_summary(self.store.forks[tip])
                for tip in sorted(self.store.forks)
            ]
            winner_tip, winner_chain = self._winning_fork()
            adoptable: list[dict] = []
            if winner_tip != self.store.tip_hash():
                adoptable.append(self._fork_summary(winner_chain))
            return 200, {
                "canonical": canonical,
                "candidates": candidates,
                "adoptable": adoptable,
            }

    def adopt_fork(self, tip_hash: object) -> tuple[int, dict]:
        """POST /v1/forks/{tip_hash}/adopt — atomically switch to the winner.

        Unknown tips return 404; adopting anything other than the current
        winning (longest / smallest-tip-hash) chain returns 409. Adoption
        replaces the canonical chain and mempool in one atomic write that
        advances the generation and rebuilds all indexes; transactions unique
        to the old chain's confirmed history return to the mempool, while
        pending-block transactions never enter it.
        """
        if not crypto.is_hex64(tip_hash):
            return 404, {"error": "unknown fork tip"}
        with self.store.lock:
            self._prune_expired_syncs()
            fork = self.store.forks.get(tip_hash)
            if fork is None:
                return 404, {"error": "unknown fork tip"}
            winner_tip, _ = self._winning_fork()
            if winner_tip != tip_hash:
                return 409, {"error": "only the winning fork can be adopted"}
            old_chain = self.store.chain
            old_pending = dict(self.store.pending)
            self.store.forks.pop(tip_hash)
            self.store.replace_chain(fork)
            # An adopted synced tip keeps its sync records (queryable until
            # expiry); record the adoption once per provenance entry. The
            # adopted tip summary is frozen from the adopted fork itself and
            # is never rewritten by later expiry.
            adopted_summary = self._fork_summary(fork)
            adopted_keys = sorted(
                key
                for key, rec in self.store.syncs.items()
                if rec["tip_hash"] == tip_hash
            )
            for rec_source, request_id in adopted_keys:
                self.store.append_audit_event(
                    EVENT_SYNC_ADOPTED,
                    {
                        "source": rec_source,
                        "request_id": request_id,
                        "tip_hash": tip_hash,
                        "expires_at": self.store.syncs[
                            (rec_source, request_id)
                        ]["expires_at"],
                        "height": adopted_summary["height"],
                        "length": adopted_summary["length"],
                        "status": adopted_summary["status"],
                    },
                )
            try:
                self.store.save()
            except BaseException:
                # Restore the pre-adoption in-memory state on a failed write.
                self.store.chain = old_chain
                self.store.pending = old_pending
                self.store.forks[tip_hash] = fork
                self.store.rebuild_derived()
                self.store.truncate_audit_events(len(adopted_keys))
                raise
            return 200, self._fork_summary(fork)

    def export_fork(self, tip_hash: object) -> tuple[int, dict]:
        """GET /v1/forks/{tip_hash}/export — full export of a candidate fork.

        Only stored candidates are exportable: the canonical tip, an unknown
        tip and a malformed tip hash (not 64 lowercase hex chars) all return
        404. The response carries exactly five fields — the fork descriptor
        (tip_hash, height, length, status, all describing the tip block) plus
        the full block list including the genesis block, every transaction's
        signature and an optional pending tip — and can be resubmitted to
        POST /v1/forks/candidates verbatim.
        """
        if not crypto.is_hex64(tip_hash):
            return 404, {"error": "unknown fork tip"}
        with self.store.lock:
            fork = self.store.forks.get(tip_hash)
            if fork is None:
                return 404, {"error": "unknown fork tip"}
            body = self._fork_summary(fork)
            body["blocks"] = [block.to_dict() for block in fork]
            return 200, body

    # -- incremental chain ranges --------------------------------------------

    RANGE_DEFAULT_LIMIT = 100
    RANGE_MAX_LIMIT = 500

    @staticmethod
    def _anchor_descriptor(block: Block) -> dict:
        """Public range anchor shape: {height, block_hash}."""
        return {"height": block.height, "block_hash": block.block_hash}

    def get_chain_range(self, params: dict) -> tuple[int, dict]:
        """GET /v1/chain/range — the canonical blocks strictly after an anchor.

        Query parameters: ``after_height`` (a non-negative decimal anchor
        height) and ``after_hash`` (the anchor block's hash, 64 lowercase hex
        characters), both required, plus ``limit`` (default 100, range 1-500).
        Every value must follow the strict decimal/hex format used by the
        other query endpoints; a repeated parameter is rejected by the HTTP
        layer.

        Returns, under the store lock,
        ``{anchor, blocks, canonical, next_height}``: ``anchor`` is
        ``{height, block_hash}`` naming the block the page starts *after*;
        ``blocks`` are the complete blocks following it (full documents
        including transactions; a pending tip block is exported too), up to
        ``limit``; ``canonical`` is the current chain descriptor S;
        ``next_height`` is the height immediately after the returned page, or
        ``null`` when the page already ends at the chain tip. A well-formed
        but unknown anchor height returns 404; a malformed anchor hash returns
        400; an anchor hash that does not match the block at that height
        returns 409.
        """
        after_height_raw = params.get("after_height")
        after_hash = params.get("after_hash")
        if after_height_raw is None:
            return 400, {"error": "missing parameter: after_height"}
        if after_hash is None:
            return 400, {"error": "missing parameter: after_hash"}
        after_height = _parse_decimal(after_height_raw)
        if after_height is None:
            return 400, {"error": "after_height must be a non-negative decimal"}
        if not crypto.is_hex64(after_hash):
            return 400, {"error": "after_hash must be 64 lowercase hex characters"}
        limit = self.RANGE_DEFAULT_LIMIT
        if params.get("limit") is not None:
            parsed = _parse_decimal(params["limit"])
            if parsed is None or not 1 <= parsed <= self.RANGE_MAX_LIMIT:
                return 400, {"error": "limit must be a decimal between 1 and 500"}
            limit = parsed

        with self.store.lock:
            anchor_block = self.store.block_at(after_height)
            if anchor_block is None:
                return 404, {"error": "anchor block not found"}
            if after_hash is not None and after_hash != anchor_block.block_hash:
                return 409, {
                    "error": "after_hash does not match the block at after_height"
                }
            page = self.store.chain[
                after_height + 1 : after_height + 1 + limit
            ]
            page_end_height = page[-1].height if page else anchor_block.height
            if page_end_height < self.store.chain[-1].height:
                next_height = page_end_height + 1
            else:
                next_height = None
            return 200, {
                "anchor": self._anchor_descriptor(anchor_block),
                "blocks": [block.to_dict() for block in page],
                "canonical": self._fork_summary(self.store.chain),
                "next_height": next_height,
            }

    # -- inter-node fork sync -------------------------------------------------

    SYNC_DEFAULT_LIMIT = 50
    SYNC_MAX_LIMIT = 200

    @staticmethod
    def _candidate_blocks(candidate: object) -> object:
        """Normalize a sync ``candidate`` to its raw blocks list.

        The candidate follows the existing export format (the five-field
        ``{tip_hash, height, length, status, blocks}`` document); the
        ``{"blocks": [...]}`` wrapper and a bare block list are accepted too.
        """
        if isinstance(candidate, dict):
            return candidate.get("blocks")
        return candidate

    @staticmethod
    def _candidate_fingerprint(blocks_raw: list) -> str:
        """Stable content fingerprint of a candidate's raw block list.

        Used to decide whether a same-key retry carries the same candidate
        content. Key order and whitespace are normalized so two documents that
        serialize the same blocks identically compare equal.
        """
        return hashlib.sha256(
            json.dumps(blocks_raw, sort_keys=True, ensure_ascii=False).encode("utf-8")
        ).hexdigest()

    def _prune_expired_syncs(self) -> list[str]:
        """Sweep expired sync records and persist the sweep atomically.

        A candidate received through a sync lives only while its record is
        unexpired; on expiry both the record and its still-stored candidate fork
        are dropped, together and in a single atomic save that advances the
        generation. Candidates submitted directly (no sync record) never
        expire, and an adopted tip is no longer in ``forks`` (it is on the
        canonical chain), so its expiring audit record leaves the chain
        untouched. If the write fails the pre-cleanup records and forks are
        restored so no success is ever reported for an un-persisted sweep.
        Caller must hold the store lock. Returns the pruned tip hashes.
        """
        expired_tips, removed = self.store.prune_syncs()
        if not removed:
            return expired_tips
        removed_forks: dict[str, list] = {}
        canonical_hashes = {block.block_hash for block in self.store.chain}
        # The same tip could theoretically be referenced by another live
        # record; only drop a fork nothing still points at.
        live_tips = {rec["tip_hash"] for rec in self.store.syncs.values()}
        for tip in expired_tips:
            if tip in canonical_hashes or tip in live_tips:
                continue
            fork = self.store.forks.pop(tip, None)
            if fork is not None:
                removed_forks[tip] = fork
        # Record one permanent expiry event per removed sync record. A tip
        # already adopted onto the canonical chain still gets its event: the
        # record's expiry is auditable even though the chain is untouched. The
        # event freezes the originally delivered summary.
        for (rec_source, request_id), rec in sorted(removed.items()):
            self.store.append_audit_event(
                EVENT_SYNC_EXPIRED,
                {
                    "source": rec_source,
                    "request_id": request_id,
                    "tip_hash": rec["tip_hash"],
                    "expires_at": rec["expires_at"],
                    "height": rec.get("height"),
                    "length": rec.get("length"),
                    "status": rec.get("status"),
                },
            )
        try:
            self.store.save()
        except BaseException:
            # Restore the pre-cleanup state: a failed write must neither leave
            # the records gone nor their candidates orphaned, nor the events
            # durably visible.
            self.store.truncate_audit_events(len(removed))
            self.store.restore_syncs(removed, removed_forks)
            raise
        return expired_tips

    def _tip_descriptor(self, tip_hash: str) -> dict | None:
        """Resolve (height/length/status) for a synced tip.

        Looks the candidate up among stored forks first, then among canonical
        blocks, so audit rows remain available after the candidate is adopted.
        """
        fork = self.store.forks.get(tip_hash)
        if fork is not None:
            return self._fork_summary(fork)
        for block in self.store.chain:
            if block.block_hash == tip_hash:
                return {
                    "tip_hash": block.block_hash,
                    "height": block.height,
                    # Length counts every block including the genesis block.
                    "length": block.height + 1,
                    "status": block.status,
                }
        return None

    def submit_fork_sync(self, payload: object) -> tuple[int, dict]:
        """POST /v1/forks/sync — receive a candidate chain from another node.

        The request carries ``source``, ``request_id``, ``expires_at`` (Unix
        seconds) and ``candidate`` (an export-format fork document).

        Authorization. A *new* source+request_id pair is accepted only when the
        source is registered in the persistent trust registry with status
        ``active`` and an ``expires_at`` still in the future. An unknown,
        revoked or registry-expired source is rejected 403 before the candidate
        is examined. A retry on a still-live recorded key bypasses the registry
        check entirely: the recorded result must keep replaying even after the
        source has since been rotated, revoked or expired.

        After authorization (and only then) the candidate is re-validated
        exactly like a direct candidate submission (canonical genesis,
        consecutive heights and prev_hash linkage, recomputed block hashes and
        Merkle roots, tx_id and Ed25519 signatures, unique ascending tx_ids,
        endowment replay, pending-only-at-tip).

        Status precedence: malformed envelope fields are 400; an unauthorized
        source is 403; a well-formed new request whose ``expires_at`` is not
        later than now is 410; a well-formed but failing candidate chain (or a
        tampered candidate summary) is 400. Returns 201 on first acceptance
        with ``{tip_hash, height, length, status, expires_at}``. A retry with
        the same source + request_id and identical content replays the original
        result as 200; the same key with different content returns 409, as does
        a duplicate tip already known.
        """
        if not isinstance(payload, dict):
            return 400, {"error": "request body must be a JSON object"}
        for field in ("source", "request_id", "expires_at", "candidate"):
            if field not in payload:
                return 400, {"error": f"missing field: {field}"}

        source = payload["source"]
        request_id = payload["request_id"]
        expires_at = payload["expires_at"]
        candidate = payload["candidate"]

        if not isinstance(source, str) or not source:
            return 400, {"error": "field 'source' must be a non-empty string"}
        if not isinstance(request_id, str) or not request_id:
            return 400, {"error": "field 'request_id' must be a non-empty string"}
        if isinstance(expires_at, bool) or not isinstance(expires_at, int):
            return 400, {"error": "field 'expires_at' must be a Unix-seconds integer"}

        blocks_raw = self._candidate_blocks(candidate)
        if not isinstance(blocks_raw, list):
            return 400, {"error": "field 'candidate' must contain a 'blocks' list"}

        with self.store.lock:
            self._prune_expired_syncs()

            key = (source, request_id)
            existing = self.store.syncs.get(key)

            if existing is None:
                # Authorization gate for new deliveries only: the source must
                # be an active, unexpired entry of the persistent trust
                # registry. Unknown, revoked or registry-expired sources are
                # refused 403 before the candidate is examined. A retry on a
                # still-live key skips this, so a recorded result keeps
                # replaying even after the source has since been rotated,
                # revoked or expired.
                now = time.time()
                trusted = self.store.trust_sources.get(source)
                if (
                    trusted is None
                    or trusted["status"] != TRUST_ACTIVE
                    or trusted["expires_at"] <= now
                ):
                    return 403, {"error": "source is not an active trusted source"}
                # The request's own deadline is checked next, still before the
                # candidate chain is examined: a well-formed request whose
                # expiry is not later than now is gone (410).
                if expires_at <= now:
                    return 410, {"error": "sync request has expired"}

            # Re-validate the whole candidate chain and recompute the tip
            # summary BEFORE any idempotency decision: a request whose supplied
            # tip_hash/height/length/status were tampered with must fail 400,
            # never be answered with the cached 200 for its source+request_id.
            try:
                fork = self.store.validate_fork_blocks(blocks_raw)
            except ValueError as exc:
                return 400, {"error": str(exc)}
            summary = self._fork_summary(fork)
            if isinstance(candidate, dict):
                for field in ("tip_hash", "height", "length", "status"):
                    if field in candidate and candidate[field] != summary[field]:
                        return 400, {
                            "error": f"candidate field {field!r} does not match the blocks"
                        }
            tip_hash = fork[-1].block_hash
            # Fingerprint the *canonicalized* parsed blocks, not the raw
            # request list, so recovery (which re-parses the stored fork)
            # recomputes an identical fingerprint regardless of insignificant
            # serialization differences in the original submission.
            canonical_blocks = [block.to_dict() for block in fork]
            fingerprint = self._candidate_fingerprint(canonical_blocks)

            if existing is not None:
                # A retry on a live key is idempotent only when it carries the
                # identical candidate content; a changed body conflicts 409.
                if fingerprint != existing["fingerprint"]:
                    return 409, {
                        "error": "request_id already used with different content"
                    }
                # Replay the ORIGINAL result frozen at first reception; only
                # legacy records without a frozen summary resolve live.
                descriptor: dict | None = None
                if existing.get("height") is not None:
                    descriptor = {
                        "tip_hash": existing["tip_hash"],
                        "height": existing["height"],
                        "length": existing["length"],
                        "status": existing["status"],
                    }
                if descriptor is None:
                    descriptor = self._tip_descriptor(existing["tip_hash"]) or {
                        "tip_hash": existing["tip_hash"],
                        "height": None,
                        "length": None,
                        "status": None,
                    }
                return 200, {
                    "tip_hash": descriptor["tip_hash"],
                    "height": descriptor.get("height"),
                    "length": descriptor.get("length"),
                    "status": descriptor.get("status"),
                    "expires_at": existing["expires_at"],
                }

            if any(tip_hash == block.block_hash for block in self.store.chain):
                return 409, {"error": "fork is identical to the canonical chain"}
            if tip_hash in self.store.forks:
                return 409, {
                    "error": "candidate fork already exists",
                    "tip_hash": tip_hash,
                }

            self.store.forks[tip_hash] = fork
            self.store.syncs[key] = {
                "tip_hash": tip_hash,
                "expires_at": expires_at,
                "fingerprint": fingerprint,
                # The tip summary is frozen at reception: later adoption or
                # expiry never rewrites it, so the history always reports what
                # was originally delivered.
                "height": summary["height"],
                "length": summary["length"],
                "status": summary["status"],
            }
            self.store.append_audit_event(
                EVENT_SYNC_RECEIVED,
                {
                    "source": source,
                    "request_id": request_id,
                    "tip_hash": tip_hash,
                    "expires_at": expires_at,
                    "height": summary["height"],
                    "length": summary["length"],
                    "status": summary["status"],
                },
            )
            try:
                self.store.save()
            except BaseException:
                # Roll back the candidate, its metadata and the audit event
                # together so a failed write never leaves one without the others.
                self.store.syncs.pop(key, None)
                self.store.forks.pop(tip_hash, None)
                self.store.truncate_audit_events(1)
                raise

            result = dict(summary)
            result["expires_at"] = expires_at
            return 201, result

    # -- incremental inter-node range sync -----------------------------------

    @staticmethod
    def _range_tip_summary(anchor: dict, tail: list) -> dict:
        """Recompute the delivered chain's tip descriptor from anchor + tail."""
        tip = tail[-1]
        return {
            "tip_hash": tip.block_hash,
            "height": tip.height,
            # The assembled length counts the canonical prefix (anchor height
            # + 1 blocks) plus every delivered tail block.
            "length": anchor["height"] + 1 + len(tail),
            "status": tip.status,
        }

    def submit_fork_sync_range(self, payload: object) -> tuple[int, dict]:
        """POST /v1/forks/sync/range — receive an incremental chain range.

        The request carries ``source``, ``request_id``, ``expires_at`` (Unix
        seconds), ``anchor`` (``{height, block_hash}`` naming the canonical
        block the range starts *after*), ``blocks`` (a non-empty list of
        complete blocks starting at the next height) and ``tip`` (the
        mandatory closed summary ``{tip_hash, height, length, status}`` of the
        delivered chain: exactly those four fields, a 64-hex tip_hash, a
        non-boolean non-negative height, a non-boolean positive length and a
        pending/confirmed status). Any structural, type or summary violation
        is 400, decided BEFORE the source is authorized and before any
        candidate, fork, sync record, audit event or generation is touched.

        A new request follows the full-sync order: envelope format validation
        (400), then the source authorization gate (403), then the request
        deadline (410). The anchor must then match the *current* canonical
        chain: an unknown anchor height or a hash mismatch is a stale anchor
        (409). The tail is prepended with the canonical prefix and put through
        the existing whole-chain re-validation (genesis connection,
        consecutive heights/prev_hash, recomputed block hashes and Merkle
        roots, tx_id/Ed25519 verification, global uniqueness and ordering,
        endowment replay, pending-only-at-tip); failure is 400, as is a
        ``tip`` summary that does not recompute (height must equal the last
        block's height, length the assembled chain length including genesis,
        status the last block's status). A tip already known as the
        canonical chain or a stored candidate is 409, mirroring full sync.

        Success stores the ASSEMBLED complete candidate (keyed by its tip hash)
        together with the sync record, the range content fingerprint
        (anchor + delivered tail only) and a ``sync_received`` event in one
        atomic write; 201 returns the same five fields as a full sync. A
        same-key retry on a live record first re-validates anchor, blocks and
        the full tip STANDALONE (never re-spliced against the current
        canonical chain): a malformed or tampered body fails 400 rather than
        replaying the cached 200, identical content replays the original
        frozen result as 200 with its original ``expires_at``, and any other
        well-formed content conflicts 409. The replay is unaffected by the
        source having rotated/revoked/expired, by the request deadline having
        passed, or by the receiver's canonical chain having advanced.
        Longest-chain adoption, expiry, mempool return-to-pool and restart
        reconciliation then all operate on the stored assembled candidate
        exactly as for a full sync.
        """
        if not isinstance(payload, dict):
            return 400, {"error": "request body must be a JSON object"}
        for field in ("source", "request_id", "expires_at", "anchor", "blocks", "tip"):
            if field not in payload:
                return 400, {"error": f"missing field: {field}"}

        source = payload["source"]
        request_id = payload["request_id"]
        expires_at = payload["expires_at"]
        anchor_raw = payload["anchor"]
        blocks_raw = payload["blocks"]
        tip = payload["tip"]

        if not isinstance(source, str) or not source:
            return 400, {"error": "field 'source' must be a non-empty string"}
        if not isinstance(request_id, str) or not request_id:
            return 400, {"error": "field 'request_id' must be a non-empty string"}
        if isinstance(expires_at, bool) or not isinstance(expires_at, int):
            return 400, {"error": "field 'expires_at' must be a Unix-seconds integer"}
        if not isinstance(anchor_raw, dict):
            return 400, {"error": "field 'anchor' must be a JSON object"}
        anchor_height = anchor_raw.get("height")
        anchor_hash = anchor_raw.get("block_hash")
        if (
            isinstance(anchor_height, bool)
            or not isinstance(anchor_height, int)
            or anchor_height < 0
        ):
            return 400, {"error": "anchor.height must be a non-negative integer"}
        if not crypto.is_hex64(anchor_hash):
            return 400, {
                "error": "anchor.block_hash must be 64 lowercase hex characters"
            }
        anchor = {"height": anchor_height, "block_hash": anchor_hash}
        if not isinstance(blocks_raw, list):
            return 400, {"error": "field 'blocks' must be a list"}
        if not blocks_raw:
            return 400, {"error": "field 'blocks' must be non-empty"}
        # The tip summary is mandatory and closed: exactly the four fields
        # tip_hash/height/length/status, each strictly typed. Any structural
        # or type violation is 400 here, before the source is authorized and
        # before any candidate, fork, sync record, audit event or generation
        # is touched.
        if not isinstance(tip, dict):
            return 400, {"error": "field 'tip' must be a JSON object"}
        if set(tip) != {"tip_hash", "height", "length", "status"}:
            return 400, {
                "error": "tip must contain exactly tip_hash, height, length and status"
            }
        if not crypto.is_hex64(tip["tip_hash"]):
            return 400, {"error": "tip.tip_hash must be 64 lowercase hex characters"}
        if (
            isinstance(tip["height"], bool)
            or not isinstance(tip["height"], int)
            or tip["height"] < 0
        ):
            return 400, {"error": "tip.height must be a non-negative integer"}
        if (
            isinstance(tip["length"], bool)
            or not isinstance(tip["length"], int)
            or tip["length"] < 1
        ):
            return 400, {"error": "tip.length must be a positive integer"}
        if tip["status"] not in (STATUS_PENDING, STATUS_CONFIRMED):
            return 400, {"error": "tip.status must be 'pending' or 'confirmed'"}

        with self.store.lock:
            self._prune_expired_syncs()
            key = (source, request_id)
            existing = self.store.syncs.get(key)

            if existing is not None:
                # Idempotent replay on a live key. The tail is re-verified
                # STANDALONE (never re-spliced against the current canonical
                # chain) and its supplied tip summary recomputed BEFORE the
                # idempotency decision — exactly like a full-sync retry, where
                # a malformed/tampered body fails 400 rather than replaying the
                # cached 200. Identical range content then replays the original
                # frozen result as 200 even after the source has rotated,
                # revoked or expired OR the receiver's canonical chain has
                # advanced; changed content conflicts 409. The authorization
                # gate is bypassed for retries.
                try:
                    tail = self.store.validate_range_tail(anchor, blocks_raw)
                except ValueError as exc:
                    return 400, {"error": str(exc)}
                recomputed_tip = self._range_tip_summary(anchor, tail)
                if tip != recomputed_tip:
                    return 400, {"error": "tip summary does not match the blocks"}
                fingerprint = self.store.range_fingerprint(anchor, tail)
                if fingerprint != existing["fingerprint"]:
                    return 409, {
                        "error": "request_id already used with different content"
                    }
                descriptor = None
                if existing.get("height") is not None:
                    descriptor = {
                        "tip_hash": existing["tip_hash"],
                        "height": existing["height"],
                        "length": existing["length"],
                        "status": existing["status"],
                    }
                if descriptor is None:
                    descriptor = self._tip_descriptor(existing["tip_hash"]) or {
                        "tip_hash": existing["tip_hash"],
                        "height": None,
                        "length": None,
                        "status": None,
                    }
                return 200, {
                    "tip_hash": descriptor["tip_hash"],
                    "height": descriptor.get("height"),
                    "length": descriptor.get("length"),
                    "status": descriptor.get("status"),
                    "expires_at": existing["expires_at"],
                }

            # New delivery follows the full-sync order: authorization (403),
            # then the request deadline (410), before the anchor or chain is
            # examined.
            now = time.time()
            trusted = self.store.trust_sources.get(source)
            if (
                trusted is None
                or trusted["status"] != TRUST_ACTIVE
                or trusted["expires_at"] <= now
            ):
                return 403, {"error": "source is not an active trusted source"}
            if expires_at <= now:
                return 410, {"error": "sync request has expired"}

            # The anchor must match the current canonical chain; an unknown
            # height or a mismatched hash is a stale anchor (409).
            anchor_block = self.store.block_at(anchor_height)
            if anchor_block is None or anchor_block.block_hash != anchor_hash:
                return 409, {"error": "anchor does not match the current canonical chain"}

            # Splice the canonical prefix and run the existing whole-chain
            # revalidation: blocks start at the next height and stay
            # consecutive, prev_hash links onto the anchor, recomputed block
            # hashes/Merkle roots, tx_id/Ed25519 verification, global
            # uniqueness and block ordering, endowment replay, and
            # pending-only-at-tip. Failure is 400.
            assembled_raw = [
                block.to_dict() for block in self.store.chain[: anchor_height + 1]
            ]
            assembled_raw.extend(
                block_raw for block_raw in blocks_raw
            )
            try:
                fork = self.store.validate_fork_blocks(assembled_raw)
            except ValueError as exc:
                return 400, {"error": str(exc)}
            summary = self._fork_summary(fork)
            tail = fork[anchor_height + 1 :]
            recomputed_tip = self._range_tip_summary(anchor, tail)
            if summary != recomputed_tip:
                return 400, {"error": "range does not assemble onto the canonical chain"}
            if tip != recomputed_tip:
                return 400, {"error": "tip summary does not match the blocks"}
            fingerprint = self.store.range_fingerprint(anchor, tail)
            tip_hash = fork[-1].block_hash

            if any(tip_hash == block.block_hash for block in self.store.chain):
                return 409, {"error": "fork is identical to the canonical chain"}
            if tip_hash in self.store.forks:
                return 409, {
                    "error": "candidate fork already exists",
                    "tip_hash": tip_hash,
                }

            # Persist the ASSEMBLED candidate so adoption, expiry cleanup and
            # restart never need to re-splice it against a later canonical,
            # alongside the range payload and its range-content fingerprint.
            self.store.forks[tip_hash] = fork
            self.store.syncs[key] = {
                "tip_hash": tip_hash,
                "expires_at": expires_at,
                "fingerprint": fingerprint,
                "height": summary["height"],
                "length": summary["length"],
                "status": summary["status"],
                "range": {
                    "anchor": dict(anchor),
                    "blocks": [block.to_dict() for block in tail],
                },
            }
            self.store.append_audit_event(
                EVENT_SYNC_RECEIVED,
                {
                    "source": source,
                    "request_id": request_id,
                    "tip_hash": tip_hash,
                    "expires_at": expires_at,
                    "height": summary["height"],
                    "length": summary["length"],
                    "status": summary["status"],
                },
            )
            try:
                self.store.save()
            except BaseException:
                # Roll back the assembled candidate, its range record and the
                # audit event together: a failed write changes nothing.
                self.store.syncs.pop(key, None)
                self.store.forks.pop(tip_hash, None)
                self.store.truncate_audit_events(1)
                raise

            result = dict(summary)
            result["expires_at"] = expires_at
            return 201, result

    def list_fork_syncs(self, params: dict) -> tuple[int, dict]:
        """GET /v1/forks/sync — audit listing of received sync candidates.

        Filters: ``source`` (exact), ``min_height`` and ``max_height``.
        ``limit`` defaults to 50 and must be 1-200; ``cursor`` defaults to 0.
        Every numeric value must be a plain decimal without leading zeros; a
        malformed value returns 400. Rows are ordered by
        ``(height, tip_hash, source)``; ``cursor == total`` returns an empty
        page, ``cursor > total`` returns 400. Each item carries
        ``source, request_id, tip_hash, height, length, status, expires_at``.
        """
        source = params.get("source")
        if source is not None and (not isinstance(source, str) or not source):
            return 400, {"error": "source must be a non-empty string"}

        min_height = None
        if params.get("min_height") is not None:
            min_height = _parse_decimal(params["min_height"])
            if min_height is None:
                return 400, {"error": "min_height must be a non-negative decimal"}
        max_height = None
        if params.get("max_height") is not None:
            max_height = _parse_decimal(params["max_height"])
            if max_height is None:
                return 400, {"error": "max_height must be a non-negative decimal"}
        if min_height is not None and max_height is not None and min_height > max_height:
            return 400, {"error": "min_height must not exceed max_height"}

        limit = self.SYNC_DEFAULT_LIMIT
        if params.get("limit") is not None:
            parsed = _parse_decimal(params["limit"])
            if parsed is None or not 1 <= parsed <= self.SYNC_MAX_LIMIT:
                return 400, {"error": "limit must be a decimal between 1 and 200"}
            limit = parsed
        cursor = 0
        if params.get("cursor") is not None:
            parsed = _parse_decimal(params["cursor"])
            if parsed is None:
                return 400, {"error": "cursor must be a non-negative decimal"}
            cursor = parsed

        with self.store.lock:
            self._prune_expired_syncs()
            rows: list[dict] = []
            for (rec_source, request_id), rec in self.store.syncs.items():
                if source is not None and rec_source != source:
                    continue
                descriptor = self._tip_descriptor(rec["tip_hash"])
                if descriptor is None:
                    continue
                if min_height is not None and descriptor["height"] < min_height:
                    continue
                if max_height is not None and descriptor["height"] > max_height:
                    continue
                rows.append(
                    {
                        "source": rec_source,
                        "request_id": request_id,
                        "tip_hash": descriptor["tip_hash"],
                        "height": descriptor["height"],
                        "length": descriptor["length"],
                        "status": descriptor["status"],
                        "expires_at": rec["expires_at"],
                    }
                )

        rows.sort(key=lambda row: (row["height"], row["tip_hash"], row["source"]))
        total = len(rows)
        if cursor > total:
            return 400, {"error": "cursor is beyond the result set"}
        items = rows[cursor : cursor + limit]
        next_cursor = cursor + limit if cursor + limit < total else None
        return 200, {"items": items, "total": total, "next_cursor": next_cursor}


    SYNC_HISTORY_KINDS = (
        EVENT_SYNC_RECEIVED,
        EVENT_SYNC_ADOPTED,
        EVENT_SYNC_EXPIRED,
    )
    SYNC_HISTORY_DEFAULT_LIMIT = 50
    SYNC_HISTORY_MAX_LIMIT = 200

    def list_fork_sync_history(self, params: dict) -> tuple[int, dict]:
        """GET /v1/forks/sync/history — paginated sync lifecycle history.

        Backed by the append-only audit log: one row per durable
        ``sync_received`` / ``sync_adopted`` / ``sync_expired`` event. Every
        row freezes the tip summary (height/length/status) captured when the
        event was recorded, so adoption and expiry never rewrite past rows and
        an adopted-then-expired record stays auditable after the sync metadata
        is gone.

        Filters (AND-combined): ``source`` (exact), ``tip_hash`` (exact, must
        be 64 lowercase hex characters — a malformed value is 400 while an
        unknown one simply yields an empty page), ``kind`` (one of the three
        sync kinds; unknown 400), ``min_height`` / ``max_height``. ``limit``
        defaults to 50 and must be 1-200; ``cursor`` defaults to 0. Every
        numeric value must be a plain non-negative decimal with no leading
        zeros (except ``0`` itself); signs, whitespace, decimals and repeated
        parameters are rejected before anything else. Rows are ordered by
        ``(height, tip_hash, source, request_id, event_id)``;
        ``cursor == total`` returns an empty page, ``cursor > total`` is 400.
        """
        source = params.get("source")
        if source is not None and (not isinstance(source, str) or not source):
            return 400, {"error": "source must be a non-empty string"}

        tip_hash = params.get("tip_hash")
        if tip_hash is not None and not crypto.is_hex64(tip_hash):
            return 400, {"error": "tip_hash must be 64 lowercase hex characters"}

        kind = params.get("kind")
        if kind is not None and kind not in self.SYNC_HISTORY_KINDS:
            return 400, {
                "error": "kind must be one of sync_received, sync_adopted, "
                "sync_expired"
            }

        min_height = None
        if params.get("min_height") is not None:
            min_height = _parse_decimal(params["min_height"])
            if min_height is None:
                return 400, {"error": "min_height must be a non-negative decimal"}
        max_height = None
        if params.get("max_height") is not None:
            max_height = _parse_decimal(params["max_height"])
            if max_height is None:
                return 400, {"error": "max_height must be a non-negative decimal"}
        if min_height is not None and max_height is not None and min_height > max_height:
            return 400, {"error": "min_height must not exceed max_height"}

        limit = self.SYNC_HISTORY_DEFAULT_LIMIT
        if params.get("limit") is not None:
            parsed = _parse_decimal(params["limit"])
            if parsed is None or not 1 <= parsed <= self.SYNC_HISTORY_MAX_LIMIT:
                return 400, {"error": "limit must be a decimal between 1 and 200"}
            limit = parsed
        cursor = 0
        if params.get("cursor") is not None:
            parsed = _parse_decimal(params["cursor"])
            if parsed is None:
                return 400, {"error": "cursor must be a non-negative decimal"}
            cursor = parsed

        with self.store.lock:
            # Make any due expiry durable first, exactly like the other sync
            # queries, so its sync_expired row appears on this page too.
            self._prune_expired_syncs()
            rows: list[dict] = []
            for event in self.store.audit_events:
                event_kind = event.get("kind")
                if event_kind not in self.SYNC_HISTORY_KINDS:
                    continue
                if source is not None and event.get("source") != source:
                    continue
                if tip_hash is not None and event.get("tip_hash") != tip_hash:
                    continue
                if kind is not None and event_kind != kind:
                    continue
                # Prefer the summary frozen into the event when it was
                # recorded. Events written before summaries were frozen fall
                # back to resolving the tip live; a tip that no longer
                # resolves anywhere is omitted rather than misordered.
                height = event.get("height")
                length = event.get("length")
                status = event.get("status")
                if (
                    not isinstance(height, int)
                    or isinstance(height, bool)
                    or length is None
                    or status is None
                ):
                    descriptor = self._tip_descriptor(event.get("tip_hash"))
                    if descriptor is None:
                        continue
                    height = descriptor["height"]
                    length = descriptor["length"]
                    status = descriptor["status"]
                if min_height is not None and height < min_height:
                    continue
                if max_height is not None and height > max_height:
                    continue
                # New events always carry the deadline; a legacy adopted
                # event predating the field inherits it from its still-live
                # sync record when possible.
                expires_at = event.get("expires_at")
                if expires_at is None:
                    live_rec = self.store.syncs.get(
                        (event.get("source"), event.get("request_id"))
                    )
                    if (
                        live_rec is not None
                        and live_rec.get("tip_hash") == event.get("tip_hash")
                    ):
                        expires_at = live_rec.get("expires_at")
                rows.append(
                    {
                        "event_id": event["event_id"],
                        "kind": event_kind,
                        "at": event["at"],
                        "source": event.get("source"),
                        "request_id": event.get("request_id"),
                        "tip_hash": event.get("tip_hash"),
                        "height": height,
                        "length": length,
                        "status": status,
                        "expires_at": expires_at,
                    }
                )

        rows.sort(
            key=lambda row: (
                row["height"],
                row["tip_hash"],
                row["source"],
                row["request_id"],
                row["event_id"],
            )
        )
        total = len(rows)
        if cursor > total:
            return 400, {"error": "cursor is beyond the result set"}
        items = rows[cursor : cursor + limit]
        next_cursor = cursor + limit if cursor + limit < total else None
        return 200, {"items": items, "total": total, "next_cursor": next_cursor}

    # -- transaction index ----------------------------------------------------

    INDEX_DEFAULT_LIMIT = 50
    INDEX_MAX_LIMIT = 200

    def list_transactions(self, params: dict) -> tuple[int, dict]:
        """GET /v1/index/transactions — paginated confirmed-chain tx index.

        Pending-tip transactions are excluded. Filters (AND-combined):
        ``tx_id`` (64 lowercase hex), ``account`` (matches sender or
        recipient) and ``height``; ``limit`` (default 50, range 1-200) and
        ``cursor`` (default 0) paginate. Numeric filters must be plain
        decimals without leading zeros; any malformed value returns 400.
        Rows are ordered by (height, index, tx_id); ``index`` is the
        transaction's 0-based position inside its block, matching the Merkle
        proof index. A cursor beyond the filtered total returns 400, a cursor
        equal to it returns an empty page.
        """
        tx_id = params.get("tx_id")
        if tx_id is not None and not crypto.is_hex64(tx_id):
            return 400, {"error": "tx_id must be 64 lowercase hex characters"}
        account = params.get("account")
        if account is not None and (not isinstance(account, str) or not account):
            return 400, {"error": "account must be a non-empty string"}

        height = None
        if params.get("height") is not None:
            height = _parse_decimal(params["height"])
            if height is None:
                return 400, {"error": "height must be a non-negative decimal"}
        limit = self.INDEX_DEFAULT_LIMIT
        if params.get("limit") is not None:
            parsed = _parse_decimal(params["limit"])
            if parsed is None or not 1 <= parsed <= self.INDEX_MAX_LIMIT:
                return 400, {"error": "limit must be a decimal between 1 and 200"}
            limit = parsed
        cursor = 0
        if params.get("cursor") is not None:
            parsed = _parse_decimal(params["cursor"])
            if parsed is None:
                return 400, {"error": "cursor must be a non-negative decimal"}
            cursor = parsed

        with self.store.lock:
            rows: list[dict] = []
            for block in self.store.chain:
                if block.status != STATUS_CONFIRMED:
                    continue
                if height is not None and block.height != height:
                    continue
                for index, tx in enumerate(block.transactions):
                    if tx_id is not None and tx.tx_id != tx_id:
                        continue
                    if account is not None and account not in (tx.sender, tx.recipient):
                        continue
                    rows.append(
                        {
                            "tx_id": tx.tx_id,
                            "height": block.height,
                            "block_hash": block.block_hash,
                            "index": index,
                            "from": tx.sender,
                            "to": tx.recipient,
                            "amount": tx.amount,
                        }
                    )
        # Chain order is already (height, index) ascending; the tx_id
        # tiebreaker is implied because ids are unique within a block.
        total = len(rows)
        if cursor > total:
            return 400, {"error": "cursor is beyond the result set"}
        items = rows[cursor : cursor + limit]
        next_cursor = cursor + limit if cursor + limit < total else None
        return 200, {"items": items, "total": total, "next_cursor": next_cursor}

    # -- source trust registry ------------------------------------------------

    @staticmethod
    def _trust_record(source: str, rec: dict) -> dict:
        """Public shape of one trust-source record."""
        return {
            "source": source,
            "public_key": rec["public_key"],
            "expires_at": rec["expires_at"],
            "version": rec["version"],
            "status": rec["status"],
        }

    def _validate_trust_input(self, payload: object, require_version: bool) -> tuple | None:
        """Validate a trust registration/rotation body.

        ``source`` must be a non-empty string, ``public_key`` 64 lowercase
        hex characters and ``expires_at`` a plain (non-boolean) integer.
        Rotation/revocation additionally require a positive integer
        ``expected_version``. Returns (source, public_key, expires_at[,
        expected_version]) or None after sending a 400.
        """
        if not isinstance(payload, dict):
            return None
        for field in ("source", "public_key", "expires_at"):
            if field not in payload:
                return None
        source = payload["source"]
        public_key = payload["public_key"]
        expires_at = payload["expires_at"]
        if not isinstance(source, str) or not source:
            return None
        if not crypto.is_hex64(public_key):
            return None
        if isinstance(expires_at, bool) or not isinstance(expires_at, int):
            return None
        if not require_version:
            return source, public_key, expires_at
        expected_version = payload.get("expected_version")
        if (
            isinstance(expected_version, bool)
            or not isinstance(expected_version, int)
            or expected_version < 1
        ):
            return None
        return source, public_key, expires_at, expected_version

    """
    return hashlib.sha256(
        json.dumps(blocks_raw, sort_keys=True, ensure_ascii=False).encode("utf-8")
    ).hexdigest()

@staticmethod
def _validate_transaction(path: str, tx: Transaction) -> None:
    """Recompute a transaction's id and check its Ed25519 signature."""
    if (
        not isinstance(tx.sender, str)
        or not isinstance(tx.recipient, str)
        or not tx.sender
        or not tx.recipient
    ):
        raise StateRecoveryError(path, "transaction has invalid from/to fields")
    if (
        isinstance(tx.amount, bool)
        or not isinstance(tx.amount, int)
        or tx.amount <= 0
    ):
        raise StateRecoveryError(
            path, f"transaction {getattr(tx, 'sender', '?')} has non-positive amount"
        )
    if not isinstance(tx.signature, str) or not tx.signature:
        raise StateRecoveryError(path, "transaction is missing a signature")
    if not crypto.verify_signature(tx.sender, tx.message, tx.signature):
        raise StateRecoveryError(
            path, f"transaction {tx.tx_id} has an invalid signature"
        )

@staticmethod
def create_genesis() -> Block:
    # The genesis block is born confirmed.
    return Block.create(
        height=0,
        prev_hash=GENESIS_PREV_HASH,
        transactions=[],
        status=STATUS_CONFIRMED,
    )

def _compute_derived(self) -> tuple[dict[str, int], dict[str, dict]]:
    """Build the confirmed-only transaction index and account activity.

    Pending blocks are excluded: only confirmed blocks contribute to
    balances and to the tx_id -> height index. Pure: it returns fresh
    dicts and never mutates store state, so callers can compute a
    prospective view and publish it only after a successful write.
    """
    tx_index: dict[str, int] = {}
    accounts: dict[str, dict] = {}
    for block in self.chain:
        if block.status != STATUS_CONFIRMED:
            continue
        for tx in block.transactions:
            tx_index[tx.tx_id] = block.height
            for account in (tx.sender, tx.recipient):
                entry = accounts.setdefault(
                    account, {"sent": 0, "received": 0, "transactions": []}
                )
                entry["transactions"].append(tx.tx_id)
            accounts[tx.sender]["sent"] += tx.amount
            accounts[tx.recipient]["received"] += tx.amount
    return tx_index, accounts

def rebuild_derived(self) -> None:
    """Rebuild the confirmed-only transaction index and account activity.

    Pending blocks are excluded: only confirmed blocks contribute to
    balances and to the tx_id -> height index.
    """
    self.tx_index, self.accounts = self._compute_derived()

def save(self) -> None:
    """Atomically persist chain, state, pending set, index and accounts.

    The new state is first written to a uniquely named ``.ledger-*``
    snapshot in the same directory and force-fsynced; only after that does
    an atomic ``os.replace`` promote it to the main file. A crash between
    the fsync and the promotion leaves the snapshot behind, where the
    startup scan finds it as a recovery candidate. The in-memory
    ``generation`` is advanced only after the promotion succeeds, so every
    *successful* atomic write corresponds to exactly one generation.
    """
    # Compute the prospective confirmed-only views WITHOUT publishing them:
    # they describe the *post-write* chain and must not become visible in
    # memory until the promotion succeeds. A failure anywhere below leaves
    # ``self.tx_index``/``self.accounts`` describing the last durably
    # committed chain, which is exactly the state the caller's own rollback
    # restores the rest of the fields to.
    next_index, next_accounts = self._compute_derived()
    next_generation = self.generation + 1
    # The in-memory log, its hash head and checkpoint always move together:
    # refuse to persist a document where they disagree, since that could
    # never recover. Callers append through append_audit_event(), which
    # advances both atomically.
    if self.audit_checkpoint != audit.make_checkpoint(self.audit_events):
        raise RuntimeError(
            "audit_checkpoint does not match the audit log head; refusing "
            "to persist an inconsistent snapshot"
        )
    # The current signer must agree with the newest retained history entry
    # and its seed must derive its public key, so a persisted document
    # never carries an internally inconsistent checkpoint key.
    audit_signer_state = None
    if self.audit_signer is not None:
        derived = crypto.derive_public_key(self.audit_signer["private_key"])
        latest = self.audit_signer_history[-1]
        if (
            derived != self.audit_signer["public_key"]
            or self.audit_signer["version"] != latest["version"]
            or self.audit_signer["public_key"] != latest["public_key"]
            or self.audit_signer["activated_event_id"]
            != latest["activated_event_id"]
        ):
            raise RuntimeError(
                "audit signer does not match its history; refusing to "
                "persist an inconsistent snapshot"
            )
        audit_signer_state = {
            "version": self.audit_signer["version"],
            "private_key": self.audit_signer["private_key"],
            "public_key": self.audit_signer["public_key"],
            "activated_event_id": self.audit_signer["activated_event_id"],
        }
    data = {
        "state": {
            "version": STATE_VERSION,
            "generation": next_generation,
            "height": self.chain[-1].height,
            "tip_hash": self.chain[-1].block_hash,
            "tip_status": self.chain[-1].status,
            "initial_balance": self.initial_balance,
        },
        "chain": [block.to_dict() for block in self.chain],
        "pending": [tx.to_dict() for tx in self.pending.values()],
        "index": dict(next_index),
        "accounts": next_accounts,
        "audit_checkpoint": dict(self.audit_checkpoint),
    }
    # The rotatable checkpoint key and every retained public key live in
    # the state section (not a new top-level key) and are persisted in the
    # same atomic document as the checkpoint they authenticate.
    if audit_signer_state is not None:
        data["state"]["audit_signer"] = audit_signer_state
        data["state"]["audit_signer_history"] = [
            dict(entry) for entry in self.audit_signer_history
        ]
    # Only persist a forks section when candidates exist so a chain with
    # no forks keeps the canonical snapshot layout; loads default to [].
    if self.forks:
        data["forks"] = [
            [block.to_dict() for block in fork]
            for fork in sorted(self.forks.values(), key=lambda f: f[-1].block_hash)
        ]
    # Sync metadata is persisted in the same atomic document as the
    # candidate chains it references. A range-sync record additionally
    # stores its delivered {anchor, blocks} payload so same-key retries
    # stay replayable (and re-verifiable) without re-splicing against a
    # canonical chain that may have since advanced.
    if self.syncs:
        data["syncs"] = [
            {
                "source": key[0],
                "request_id": key[1],
                "tip_hash": rec["tip_hash"],
                "expires_at": rec["expires_at"],
                "fingerprint": rec["fingerprint"],
                "height": rec.get("height"),
                "length": rec.get("length"),
                "status": rec.get("status"),
                **(
                    {"range": rec["range"]}
                    if rec.get("range") is not None
                    else {}
                ),
            }
            for key, rec in sorted(self.syncs.items())
        ]
    # Persistent source-trust registry and the keyless allowlist are part
    # of the same atomic document as every state change they describe.
    if self.trust_sources:
        data["trust_sources"] = [
            {"source": source, **self.trust_sources[source]}
            for source in sorted(self.trust_sources)
        ]
    if self.allowlist:
        data["allowlist"] = dict(sorted(self.allowlist.items()))
    # The audit trail is append-only; every trust change and every sync
    # reception/adoption/expiry is recorded here in write order.
    if self.audit_events:
        data["audit_events"] = list(self.audit_events)
    directory = os.path.dirname(os.path.abspath(self.path)) or "."
    os.makedirs(directory, exist_ok=True)
    # Hold the class-wide recovery lock while a .ledger-* snapshot exists
    # on disk, so a concurrent in-process LedgerStore construction cannot
    # scan a half-written promotion.
    with self._recovery_lock:
        fd, tmp_path = tempfile.mkstemp(
            prefix=SNAPSHOT_PREFIX,
            suffix=f".gen{next_generation}",
            dir=directory,
        )
        promoted = False
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(data, fh, ensure_ascii=False, sort_keys=True)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp_path, self.path)
            promoted = True
            self._fsync_dir(directory)
            # Promotion is durable: now publish the prospective derived
            # views and advance the generation, together and last, so a
            # successful write is the only thing that changes memory.
            self.tx_index = next_index
            self.accounts = next_accounts
            self.generation = next_generation
        finally:
            if not promoted and os.path.exists(tmp_path):
                # Promotion never happened: drop the half-written candidate so
                # it cannot masquerade as a recoverable snapshot. A candidate
                # written and fsynced *before* a crash during replace survives
                # precisely because that crash skips this cleanup.
                try:
                    os.unlink(tmp_path)
                except OSError:
                    pass

@staticmethod
def _fsync_dir(directory: str) -> None:
    """Best-effort directory fsync so a rename survives a power loss."""
    try:
        dir_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    except OSError:
        pass
    finally:
        os.close(dir_fd)

# -- chain helpers --------------------------------------------------------

def tip(self) -> Block:
    return self.chain[-1]

def tip_hash(self) -> str:
    return self.chain[-1].block_hash

def next_height(self) -> int:
    return self.chain[-1].height + 1

def tip_is_pending(self) -> bool:
    return self.chain[-1].status == STATUS_PENDING

def block_at(self, height: int) -> Block | None:
    if 0 <= height < len(self.chain) and self.chain[height].height == height:
        return self.chain[height]
    return None

def rollback_tip(self) -> Block:
    """Remove the pending tip block and return its transactions to the mempool.

    Transactions are restored de-duplicated: an id already present in the
    pending set (resubmitted while the block was unconfirmed) is kept as
    is, not overwritten. Caller must hold the lock and must have checked
    that the tip is a pending block. Does not save; callers persist.
    """
    block = self.chain.pop()
    for tx in block.transactions:
        self.pending.setdefault(tx.tx_id, tx)
    return block

# -- fork candidates ------------------------------------------------------

@staticmethod
def _valid_tx_fields(tx: Transaction) -> None:
    """Structural checks shared by candidate submission and recovery."""
    if not isinstance(tx.sender, str) or not tx.sender:
        raise ValueError("transaction has an invalid 'from' field")
    if not isinstance(tx.recipient, str) or not tx.recipient:
        raise ValueError("transaction has an invalid 'to' field")
    if isinstance(tx.amount, bool) or not isinstance(tx.amount, int) or tx.amount <= 0:
        raise ValueError("transaction amount must be a positive integer")
    if not isinstance(tx.signature, str) or not tx.signature:
        raise ValueError("transaction is missing a signature")

def _parse_verified_chain(
    self, blocks_raw: object, endowment: int, genesis: Block | None = None
) -> list[Block]:
    """Strictly validate a block list submitted as (or persisted as) a fork.

    The list must start from the canonical genesis block, connect through
    consecutive heights and prev_hash values, and carry recomputed-correct
    Merkle roots and block hashes. Transactions must have valid Ed25519
    signatures, ascending and globally unique tx_ids, and a replay from the
    per-identity endowment must never overspend. All blocks must be
    confirmed except an optional pending tip. Raises ValueError on any
    defect.
    """
    if not isinstance(blocks_raw, list) or not blocks_raw:
        raise ValueError("'blocks' must be a non-empty list")
    genesis = genesis if genesis is not None else self.chain[0]
    blocks: list[Block] = []
    seen_tx_ids: set[str] = set()
    for i, block_raw in enumerate(blocks_raw):
        if not isinstance(block_raw, dict):
            raise ValueError(f"block at position {i} is not a JSON object")
        try:
            block = Block.from_dict(block_raw)
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError(f"block {i} is malformed: {exc}") from exc
        if isinstance(block.height, bool) or block.height != i:
            raise ValueError(
                f"block at position {i} has non-consecutive height {block.height}"
            )
        expected_prev = GENESIS_PREV_HASH if i == 0 else blocks[i - 1].block_hash
        if block.prev_hash != expected_prev:
            raise ValueError(f"block {i} has a mismatched prev_hash")
        if block.status not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise ValueError(f"block {i} has unknown status {block.status!r}")
        if i == 0:
            # The candidate must connect to *the* canonical genesis.
            if (
                block.status != STATUS_CONFIRMED
                or block.transactions
                or block.block_hash != genesis.block_hash
                or block.merkle_root != genesis.merkle_root
            ):
                raise ValueError("first block must be the canonical genesis block")
        elif i < len(blocks_raw) - 1 and block.status == STATUS_PENDING:
            raise ValueError(f"pending block {i} is not the chain tip")

        txs_raw = block_raw.get("transactions")
        if not isinstance(txs_raw, list):
            raise ValueError(f"block {i} transactions must be a list")
        tx_ids: list[str] = []
        for j, tx in enumerate(block.transactions):
            self._valid_tx_fields(tx)
            if not crypto.verify_signature(tx.sender, tx.message, tx.signature):
                raise ValueError(f"block {i} transaction {j} has an invalid signature")
            stored_id = txs_raw[j].get("tx_id") if isinstance(txs_raw[j], dict) else None
            if stored_id != tx.tx_id:
                raise ValueError(
                    f"block {i} transaction {j} has a mismatched tx_id"
                )
            if tx.tx_id in seen_tx_ids:
                raise ValueError(f"duplicate transaction {tx.tx_id} in candidate")
            seen_tx_ids.add(tx.tx_id)
            tx_ids.append(tx.tx_id)
        if tx_ids != sorted(tx_ids):
            raise ValueError(f"block {i} transactions are not tx_id sorted")
        if crypto.merkle_root(tx_ids) != block.merkle_root:
            raise ValueError(f"block {i} Merkle root mismatch")
        if (
            compute_block_hash(block.height, block.prev_hash, block.merkle_root)
            != block.block_hash
        ):
            raise ValueError(f"block {i} block_hash mismatch")
        blocks.append(block)

    # Replay every transaction from the per-identity endowment; unconfirmed
    # (pending tip) transactions are included so a candidate can never hide
    # an overspend behind a pending final block.
    balances: dict[str, int] = {}
    for block in blocks:
        for tx in block.transactions:
            sender_balance = balances.get(tx.sender, endowment)
            if sender_balance < tx.amount:
                raise ValueError(
                    f"replay overspend by {tx.sender} in block {block.height}"
                )
            balances[tx.sender] = sender_balance - tx.amount
            balances[tx.recipient] = balances.get(tx.recipient, endowment) + tx.amount
    return blocks

def validate_fork_blocks(self, blocks_raw: object) -> list[Block]:
    """Validate and parse a candidate fork submitted by a client.

    The blocks must start from the canonical genesis block, connect via
    consecutive heights and prev_hash, carry correct block hashes and
    Merkle roots, unique ascending tx_ids with valid Ed25519 signatures and
    no replay overspend, and be all confirmed except an optional pending
    tip. Raises ValueError with a descriptive reason on any defect.
    """
    endowment = (
        self.initial_balance if self.initial_balance is not None else 1_000_000
    )
    return self._parse_verified_chain(blocks_raw, endowment)

@staticmethod
def validate_range_tail(anchor: dict, blocks_raw: object) -> list[Block]:
    """Strictly verify an incremental range's delivered tail standalone.

    Used both when a range delivery is first received and when range sync
    records are re-verified on restart; it never splices in (or depends on)
    the current canonical chain, so a same-key retry stays verifiable after
    the receiver's canonical chain has advanced. The tail must be a
    non-empty list of well-formed blocks whose heights start at
    ``anchor.height + 1`` and stay consecutive, whose first ``prev_hash``
    is the anchor hash (later ones linking internally), with
    recomputed-correct Merkle roots and block hashes, valid Ed25519
    signatures, tx_ids unique within the tail and ascending inside each
    block, and pending status only on its final block. Endowment replay is
    not part of this standalone check (it needs the canonical-prefix
    balances and is run on the assembled chain at first reception).
    Raises ValueError on any defect and returns the parsed tail Blocks.
    """
    if not isinstance(blocks_raw, list) or not blocks_raw:
        raise ValueError("'blocks' must be a non-empty list")
    tail: list[Block] = []
    seen_tx_ids: set[str] = set()
    expected_prev = anchor["block_hash"]
    for i, block_raw in enumerate(blocks_raw):
        if not isinstance(block_raw, dict):
            raise ValueError(f"block at position {i} is not a JSON object")
        try:
            block = Block.from_dict(block_raw)
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError(f"block {i} is malformed: {exc}") from exc
        expected_height = anchor["height"] + 1 + i
        if isinstance(block.height, bool) or block.height != expected_height:
            raise ValueError(
                f"block at position {i} has height {block.height}, "
                f"expected {expected_height}"
            )
        if block.prev_hash != expected_prev:
            raise ValueError(f"block {i} has a mismatched prev_hash")
        if block.status not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise ValueError(f"block {i} has unknown status {block.status!r}")
        if i < len(blocks_raw) - 1 and block.status == STATUS_PENDING:
            raise ValueError(f"pending block {i} is not the chain tip")
        txs_raw = block_raw.get("transactions")
        if not isinstance(txs_raw, list):
            raise ValueError(f"block {i} transactions must be a list")
        tx_ids: list[str] = []
        for j, tx in enumerate(block.transactions):
            LedgerStore._valid_tx_fields(tx)
            if not crypto.verify_signature(tx.sender, tx.message, tx.signature):
                raise ValueError(
                    f"block {i} transaction {j} has an invalid signature"
                )
            stored_id = (
                txs_raw[j].get("tx_id") if isinstance(txs_raw[j], dict) else None
            )
            if stored_id != tx.tx_id:
                raise ValueError(
                    f"block {i} transaction {j} has a mismatched tx_id"
                )
            if tx.tx_id in seen_tx_ids:
                raise ValueError(
                    f"duplicate transaction {tx.tx_id} in range delivery"
                )
            seen_tx_ids.add(tx.tx_id)
            tx_ids.append(tx.tx_id)
        if tx_ids != sorted(tx_ids):
            raise ValueError(f"block {i} transactions are not tx_id sorted")
        if crypto.merkle_root(tx_ids) != block.merkle_root:
            raise ValueError(f"block {i} Merkle root mismatch")
        if (
            compute_block_hash(block.height, block.prev_hash, block.merkle_root)
            != block.block_hash
        ):
            raise ValueError(f"block {i} block_hash mismatch")
        expected_prev = block.block_hash
        tail.append(block)
    return tail

@staticmethod
def range_fingerprint(anchor: dict, tail: list[Block]) -> str:
    """SHA-256 content fingerprint of a delivered range (anchor + tail).

    Covers exactly what the sender delivered — never the assembled
    canonical prefix — so a same-key retry keeps matching after the
    receiver's canonical chain has advanced.
    """
    payload = {
        "anchor": {
            "height": anchor["height"],
            "block_hash": anchor["block_hash"],
        },
        "blocks": [block.to_dict() for block in tail],
    }
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
    ).hexdigest()

def _parse_persisted_forks(
    self,
    forks_raw: object,
    canonical_chain: list[Block],
    endowment: int | None = None,
) -> dict[str, list[Block]]:
    """Parse persisted candidate forks, dropping invalid ones on restart.

    Every stored fork is re-validated exactly like a fresh submission
    (genesis connection, hashes, Merkle roots, signatures, uniqueness,
    replay). A fork that no longer validates is silently discarded rather
    than failing recovery of the canonical chain. Recovery of the canonical
    chain itself remains strict and still raises StateRecoveryError. The
    replay uses ``endowment`` — the value recorded in this snapshot — rather
    than the startup argument, so a different launch parameter cannot make
    a persisted fork legal or illegal.
    """
    if not isinstance(forks_raw, list):
        return {}
    if endowment is None:
        endowment = DEFAULT_INITIAL_BALANCE
    genesis = canonical_chain[0]
    forks: dict[str, list[Block]] = {}
    for entry in forks_raw:
        try:
            fork = self._parse_verified_chain(entry, endowment, genesis)
        except (ValueError, KeyError, TypeError):
            continue
        if not fork or fork[0].block_hash != genesis.block_hash:
            continue
        tip_hash = fork[-1].block_hash
        # The canonical chain (or a strict prefix of it, matched by any
        # canonical block hash) is never also stored as a candidate.
        if any(tip_hash == block.block_hash for block in canonical_chain):
            continue
        forks.setdefault(tip_hash, fork)
    return forks

def replace_chain(self, new_chain: list[Block]) -> None:
    """Atomically adopt a fork: swap the canonical chain, reconcile the
    mempool (old-chain-only confirmed transactions return de-duplicated;
    pending-block transactions never enter the pool) and rebuild indexes.
    Does not save; the caller persists.
    """
    old_confirmed_ids = {
        tx.tx_id
        for block in self.chain
        if block.status == STATUS_CONFIRMED
        for tx in block.transactions
    }
    new_ids = {tx.tx_id for block in new_chain for tx in block.transactions}
    old_tx_by_id = {
        tx.tx_id: tx
        for block in self.chain
        for tx in block.transactions
    }
    # Transactions unique to the superseded chain's confirmed history go
    # back to the mempool, de-duplicated against anything already queued.
    # Transactions from the old pending tip are not in old_confirmed_ids,
    # so they are dropped, never re-enqueued.
    for tx_id in old_confirmed_ids - new_ids:
        self.pending.setdefault(tx_id, old_tx_by_id[tx_id])
    # Transactions now on the adopted chain must leave the mempool.
    for tx_id in new_ids:
        self.pending.pop(tx_id, None)
    self.chain = new_chain
    self.rebuild_derived()

# -- sync records ---------------------------------------------------------

@staticmethod
def _make_audit_signer(version: int, activated_event_id: int) -> dict:
    """Generate a fresh Ed25519 signer record at ``version``.

    Returns the mutable current record
    ``{"version", "private_key", "public_key", "activated_event_id"}``.
    """
    private_key = crypto.generate_private_key()
    public_key = crypto.derive_public_key(private_key)
    return {
        "version": version,
        "private_key": private_key,
        "public_key": public_key,
        "activated_event_id": activated_event_id,
    }

@staticmethod
def _public_signer_entry(signer: dict) -> dict:
    """The trust-document shape of one signer version (no private key)."""
    return {
        "version": signer["version"],
        "public_key": signer["public_key"],
        "activated_event_id": signer["activated_event_id"],
    }

def sign_checkpoint(self) -> dict | None:
    """Return ``{key_version, signature}`` for the current log head.

    The signature covers Ed25519(SHA256(canonical JSON of
    ``{genesis_hash, checkpoint, key_version}``)) under the current audit
    signer. Returns None on a legacy unsigned snapshot that has not yet
    been migrated (exports then carry no checkpoint authentication).
    Caller must hold the lock.
    """
    if self.audit_signer is None:
        return None
    signature = audit.sign_checkpoint_auth(
        self.audit_signer["private_key"],
        self.chain[0].block_hash,
        self.audit_checkpoint,
        self.audit_signer["version"],
    )
    # A locally generated/validated key cannot fail; treat it as a
    # programming error rather than emitting an unsigned export.
    if signature is None:
        raise RuntimeError("current audit signer key is invalid")
    return {
        "key_version": self.audit_signer["version"],
        "signature": signature,
    }

def append_audit_event(self, kind: str, payload: dict, at: float | None = None) -> dict:
    """Append an audit event in memory with the next monotonic event_id.

    The event's ``prev_hash``/``event_hash`` links are computed against
    the current log head so the append-only hash chain stays continuous.
    The in-memory checkpoint is advanced together with the event; the
    caller persists the event, the link and the checkpoint in the same
    atomic write as the state change the event describes. Caller must
    hold the lock.
    """
    prev_hash = (
        self.audit_checkpoint["event_hash"]
        if self.audit_events
        else audit.ZERO_HASH
    )
    event = {
        "event_id": len(self.audit_events) + 1,
        "kind": kind,
        "at": time.time() if at is None else at,
        "prev_hash": prev_hash,
    }
    event.update(payload)
    event["event_hash"] = audit.event_hash(prev_hash, event)
    self.audit_events.append(event)
    self.audit_checkpoint = audit.make_checkpoint(self.audit_events)
    return event

def truncate_audit_events(self, count: int) -> None:
    """Remove the last ``count`` appended events and reset the checkpoint.

    Used by callers to roll an append back when the accompanying atomic
    write fails: the log, its hash head and the checkpoint always move
    together, so the checkpoint must return to the new (old) head.
    Caller must hold the lock.
    """
    if count:
        del self.audit_events[len(self.audit_events) - count :]
    self.audit_checkpoint = audit.make_checkpoint(self.audit_events)

def prune_syncs(
    self, now: float | None = None
) -> tuple[list[str], dict[tuple[str, str], dict]]:
    """Drop expired sync records in memory.

    A record expires once ``expires_at`` has passed. Returns the orphaned
    tip hashes together with every removed record (keyed by
    ``(source, request_id)``) so the caller can persist the sweep
    atomically and restore the pre-cleanup state if that write fails.
    Tips adopted onto the canonical chain are not present in ``forks`` and
    are simply skipped when the caller reconciles them. Does not save; the
    caller persists.
    """
    current = time.time() if now is None else now
    expired_tips: list[str] = []
    removed: dict[tuple[str, str], dict] = {}
    for key in list(self.syncs):
        rec = self.syncs[key]
        if rec["expires_at"] <= current:
            expired_tips.append(rec["tip_hash"])
            removed[key] = rec
            del self.syncs[key]
    return expired_tips, removed

def restore_syncs(
    self,
    removed: dict[tuple[str, str], dict],
    forks: dict[str, list[Block]],
) -> None:
    """Restore sync records and candidate forks removed by a failed sweep.

    Only records still missing are re-inserted, and the matching candidate
    forks are put back only when no other live record still references the
    tip. Caller must hold the lock.
    """
    for key, rec in removed.items():
        self.syncs.setdefault(key, rec)
    for tip, fork in forks.items():
        self.forks.setdefault(tip, fork)

"""HTTP server exposing the ledger REST API using the Python standard library."""
from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote

from .service import LedgerService

MAX_BODY_BYTES = 1 << 20  # 1 MiB cap on request bodies


def build_handler(service: LedgerService) -> type[BaseHTTPRequestHandler]:
    """Create a handler class closed over the given ledger service."""

    class LedgerHandler(BaseHTTPRequestHandler):
        server_version = "VerifiableLedger/1.0"

        # -- helpers --------------------------------------------------------

        def _send_json(self, status: int, body: dict) -> None:
            data = json.dumps(body, ensure_ascii=False, sort_keys=True).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _read_json(self) -> tuple[bool, object]:
            try:
                length = int(self.headers.get("Content-Length", "0"))
            except ValueError:
                return False, {"error": "invalid Content-Length"}
            if length <= 0:
                return False, {"error": "request body must be JSON"}
            if length > MAX_BODY_BYTES:
                return False, {"error": "request body too large"}
            raw = self.rfile.read(length)
            try:
                return True, json.loads(raw.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                return False, {"error": "request body must be valid JSON"}

        # -- routing --------------------------------------------------------

        def do_POST(self) -> None:  # noqa: N802 (stdlib naming)
            path = self.path.split("?", 1)[0]
            if path == "/v1/transactions":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_transaction(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/candidates":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_candidate(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync/range":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync_range(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync(payload)
                self._send_json(status, body)
            elif path == "/v1/audit/signer/rotate":
                # POST /v1/audit/signer/rotate — rotate the Ed25519 key that
                # authenticates audit export checkpoints.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.rotate_audit_signer(payload)
                self._send_json(status, body)
            elif path == "/v1/trust/sources":
                # POST /v1/trust/sources — register a trusted source.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.register_trust_source(payload)
                self._send_json(status, body)
            elif (
                path.startswith("/v1/trust/sources/")
                and (path.endswith("/rotate") or path.endswith("/revoke"))
            ):
                # POST /v1/trust/sources/{source}/rotate | /revoke
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                remainder = path[len("/v1/trust/sources/") :]
                if remainder.endswith("/rotate"):
                    source = unquote(remainder[: -len("/rotate")])
                    status, body = service.rotate_trust_source(source, payload)
                else:
                    source = unquote(remainder[: -len("/revoke")])
                    status, body = service.revoke_trust_source(source, payload)
                self._send_json(status, body)
            elif path == "/v1/trust/allowlist":
                # POST /v1/trust/allowlist — add a keyless offline-verify entry.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.add_allowlist_entry(payload)
                self._send_json(status, body)
            elif path.startswith("/v1/forks/") and path.endswith("/adopt"):
                # POST /v1/forks/{tip_hash}/adopt — a body is not required.
                if self.headers.get("Content-Length"):
                    self._read_json()
                tip_hash = unquote(path[len("/v1/forks/") : -len("/adopt")])
                status, body = service.adopt_fork(tip_hash)
                self._send_json(status, body)
            elif path == "/v1/blocks":
                # A body is not required; drain one if present.
                if self.headers.get("Content-Length"):
                    self._read_json()
                status, body = service.mine_block()
                self._send_json(status, body)
            elif path.startswith("/v1/blocks/"):
                remainder = path[len("/v1/blocks/") :]
                # POST /v1/blocks/{height}/confirm | /v1/blocks/{height}/rollback
                if self.headers.get("Content-Length"):
                    self._read_json()
                if remainder.endswith("/confirm"):
                    height = unquote(remainder[: -len("/confirm")])
                    status, body = service.confirm_block(height)
                elif remainder.endswith("/rollback"):
                    height = unquote(remainder[: -len("/rollback")])
                    status, body = service.rollback_block(height)
                else:
                    status, body = 404, {"error": "not found"}
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

        def do_DELETE(self) -> None:  # noqa: N802 (stdlib naming)
            path = self.path.split("?", 1)[0]
            if path.startswith("/v1/trust/allowlist/"):
                # DELETE /v1/trust/allowlist/{source}
                source = unquote(path[len("/v1/trust/allowlist/") :])
                status, body = service.remove_allowlist_entry(source)
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

        def do_GET(self) -> None:  # noqa: N802 (stdlib naming)
            path, _, query = self.path.partition("?")
            if path == "/v1/trust":
                status, body = service.get_trust_document()
                self._send_json(status, body)
            elif path == "/v1/audit/events":
                # GET /v1/audit/events?source=&kind=&cursor=&limit=
                params = {
                    key: values[0]
                    for key, values in parse_qs(query, keep_blank_values=True).items()
                }
                status, body = service.list_audit_events(params)
                self._send_json(status, body)
            elif path == "/v1/audit/export":
                # GET /v1/audit/export?cursor=&limit= — hash-anchored export
                # pages for offline audit verification. Repeated query
                # parameters are rejected 400 like the other strict endpoints.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.export_audit_events(params)
                self._send_json(status, body)
            elif path == "/v1/chain/range":
                # GET /v1/chain/range?after_height=&after_hash=&limit=
                # Incremental canonical-chain page after an anchor. Repeated
                # query parameters are rejected 400 like the strict endpoints.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.get_chain_range(params)
                self._send_json(status, body)
            elif path == "/v1/chain":
                status, body = service.get_chain()
                self._send_json(status, body)
            elif path == "/v1/forks/sync/history":
                # GET /v1/forks/sync/history?source=&tip_hash=&kind=&
                # min_height=&max_height=&limit=&cursor=
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.list_fork_sync_history(params)
                self._send_json(status, body)
            elif path == "/v1/forks/sync":
                # GET /v1/forks/sync?source=&min_height=&max_height=&limit=&cursor=
                params = {
                    key: values[0]
                    for key, values in parse_qs(query, keep_blank_values=True).items()
                }
                status, body = service.list_fork_syncs(params)
                self._send_json(status, body)
            elif path == "/v1/index/transactions":
                # GET /v1/index/transactions?tx_id=&account=&height=&limit=&cursor=
                params = {
                    key: values[0]
                    for key, values in parse_qs(query, keep_blank_values=True).items()
                }
                status, body = service.list_transactions(params)
                self._send_json(status, body)
            elif path.startswith("/v1/forks/") and path.endswith("/export"):
                # GET /v1/forks/{tip_hash}/export
                tip_hash = unquote(path[len("/v1/forks/") : -len("/export")])
                status, body = service.export_fork(tip_hash)
                self._send_json(status, body)
            elif path.startswith("/v1/blocks/"):
                remainder = path[len("/v1/blocks/") :]
                if "/proof/" in remainder:
                    # GET /v1/blocks/{height}/proof/{tx_id}
                    height_raw, tx_raw = remainder.split("/proof/", 1)
                    if not height_raw or not tx_raw:
                        self._send_json(404, {"error": "not found"})
                        return
                    status, body = service.get_proof(unquote(height_raw), unquote(tx_raw))
                    self._send_json(status, body)
                elif remainder.endswith("/status"):
                    # GET /v1/blocks/{height}/status
                    height = unquote(remainder[: -len("/status")])
                    status, body = service.get_block_status(height)
                    self._send_json(status, body)
                else:
                    height = unquote(remainder)
                    status, body = service.get_block(height)
                    self._send_json(status, body)
            elif path.startswith("/v1/accounts/"):
                account = unquote(path[len("/v1/accounts/") :])
                if not account:
                    self._send_json(404, {"error": "account not found"})
                    return
                status, body = service.get_account(account)
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

    return LedgerHandler


def serve(service: LedgerService, host: str, port: int) -> ThreadingHTTPServer:
    """Create and run the HTTP server (blocks until interrupted)."""
    httpd = ThreadingHTTPServer((host, port), build_handler(service))
    httpd.serve_forever()
    return httpd

"""Command line interface: send, mine, block, account, proof, confirm,
rollback, status, candidates, chain, adopt, export, index, sync, syncs,
sync-history, audit, audit-export, trust (add/rotate/revoke/export/
allowlist-add/allowlist-remove) and offline verify/audit-verify
subcommands.

The CLI talks to a running ledger server over HTTP and prints each response as
a single line of JSON with exactly the same field names as the HTTP API.

Signing a transaction locally is supported through ``send --signing-key``;
the key may be 32 raw hex bytes or ``@/path/to/ed25519-key.pem``. An already
produced signature can be passed instead with ``--from/--signature``. The
``candidates`` subcommand takes the candidate fork's block array (or a
``{"blocks": [...]}`` object) as a single JSON argument.
"""
from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from typing import Any

from . import crypto

DEFAULT_BASE_URL = os.environ.get("LEDGER_BASE_URL", "http://127.0.0.1:8080")


# -- HTTP helpers ------------------------------------------------------------


def _request(method: str, url: str, payload: dict | None) -> tuple[int, dict]:
    data = None
    headers = {"Accept": "application/json"}
    if payload is not None:
        data = json.dumps(payload, sort_keys=True).encode("utf-8")
        headers["Content-Type"] = "application/json"
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request) as response:
            return response.status, json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        try:
            body = json.loads(exc.read().decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            body = {"error": exc.reason}
        return exc.code, body
    except (urllib.error.URLError, OSError) as exc:
        return 0, {"error": f"cannot reach ledger server: {exc}"}


def _emit(status: int, body: dict) -> int:
    print(json.dumps(body, sort_keys=True, ensure_ascii=False))
    # 2xx responses are success; anything else (incl. connection failure) is 1.
    return 0 if 200 <= status < 300 else 1


# -- signing key handling ----------------------------------------------------


def _load_signing_key(spec: str):
    """Load an Ed25519 private key from raw hex or an ``@file`` (hex or PEM)."""
    from cryptography.hazmat.primitives import serialization

    if spec.startswith("@"):
        with open(spec[1:], "rb") as fh:
            material = fh.read()
    else:
        material = spec.encode("ascii")
    stripped = material.strip()
    if stripped.startswith(b"-----BEGIN"):
        key = serialization.load_pem_private_key(stripped, password=None)
    else:
        raw = bytes.fromhex(stripped.decode("ascii"))
        if len(raw) != 32:
            raise ValueError("signing key must be 32 raw bytes (64 hex chars)")
        from cryptography.hazmat.primitives.asymmetric.ed25519 import (
            Ed25519PrivateKey,
        )

        key = Ed25519PrivateKey.from_private_bytes(raw)
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

    if not isinstance(key, Ed25519PrivateKey):
        raise ValueError("signing key is not an Ed25519 private key")
    return key


def _public_key_hex(key) -> str:
    from cryptography.hazmat.primitives import serialization

    return key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


# -- subcommands -------------------------------------------------------------


def cmd_send(args: argparse.Namespace) -> int:
    if args.signing_key:
        try:
            key = _load_signing_key(args.signing_key)
        except (ValueError, OSError, TypeError) as exc:
            return _emit(400, {"error": f"invalid signing key: {exc}"})
        sender = _public_key_hex(key)
        message = crypto.canonical_message(sender, args.to, args.amount)
        signature = key.sign(message).hex()
    else:
        if not args.sender or not args.signature:
            return _emit(
                400,
                {"error": "provide either --signing-key or both --from and --signature"},
            )
        sender, signature = args.sender, args.signature

    payload = {
        "from": sender,
        "to": args.to,
        "amount": args.amount,
        "signature": signature,
    }
    status, body = _request("POST", f"{args.base_url}/v1/transactions", payload)
    return _emit(status, body)


