from ledger import crypto

T=['%064d'%i for i in range(10)]
def make_proof(n, i, bad=None):
    leaves=[crypto.account_state_leaf('acct%03d'%j, 100*j, [T[j%10]]) for j in range(n)]
    root=crypto.account_state_root(leaves)
    sib=crypto.merkle_proof(leaves,i)
    p={'account':'acct%03d'%i,'balance':100*i,'confirmed_transactions':[T[i%10]],
       'index':i,'state_root':root,'height':n,'block_hash':'h'*64,'siblings':sib}
    return p, root

ok=True
for n in range(1,12):
    for i in range(n):
        p,root=make_proof(n,i)
        if not crypto.verify_account_proof(p,root,n,'h'*64): ok=False; print('VALID FAIL',n,i)
        # wrong anchor/root/balance
        if crypto.verify_account_proof(p,'0'*64,n,'h'*64): ok=False; print('BADROOT',n,i)
        if crypto.verify_account_proof(p,root,n+1,'h'*64): ok=False; print('BADHEIGHT',n,i)
        if crypto.verify_account_proof(p,root,n,'0'*64): ok=False; print('BADHASH',n,i)
        q=dict(p); q['balance']=q['balance']+1
        if crypto.verify_account_proof(q,root,n,'h'*64): ok=False; print('BADBAL',n,i)
        # tamper a direction
        if p['siblings']:
            r=dict(p); s=list(r['siblings']); s[0]=dict(s[0])
            s[0]['direction']='left' if s[0]['direction']=='right' else 'right'
            r['siblings']=s
            if crypto.verify_account_proof(r,root,n,'h'*64): ok=False; print('BADDIR',n,i)
        # bogus out-of-range index
        r=dict(p); r['index']=i+(1<<len(p['siblings']))
        if crypto.verify_account_proof(r,root,n,'h'*64): ok=False; print('BADIDX range',n,i)
# single leaf tree with non-zero index
p,root=make_proof(1,0); p['index']=5
if crypto.verify_account_proof(p,root,1,'h'*64): ok=False; print('single-leaf index accepted')
# malformed inputs
for bad in [None, 5, [], {}, {'x':1}]:
    if crypto.verify_account_proof(bad,'0'*64,0,'0'*64): ok=False; print('malformed accepted',bad)
print('ALL OK' if ok else 'FAILURES')
